      metric:{low:Math.round(st.salary*1.02), high:ask, you:Math.round(Math.min(ask*0.92, st.salary*1.10)), them:ask},
      leverage:clamp(70 - st.skill*3 - (st.morale||50)/8, 5, 92), maxRounds:3,
