      const gain = clamp(spend/(Math.max(1,(S.biz.revenue||0)*0.35))*14, 3, 18);
      S.biz.auto = clamp((S.biz.auto||0)+gain, 0, 100);
      S.biz.quality = clamp(S.biz.quality + gain*0.25, 0, 100);
