/* Automatic sync. The game is local-first: it never waits on the network and
   never fails because of it. If a session exists, the record is pulled and
   pushed in the background; if anything goes wrong the device copy simply
   carries on and the next successful sync merges the two. */
let _syncing = false;

/* Pull first, then push: a device that has been away should receive before it
   imposes. Errors are swallowed by design - sync is a convenience, never a
   dependency. */
async function cloudSyncBackground(){
  if(_syncing) return false;
  if(!cloudConfigured()) return false;
  if(typeof navigator!=='undefined' && navigator.onLine===false) return false;
  if(!cloudReady()) return false;
  _syncing = true;
  let ok = false;
  try{
    if(!cloudSessionValid() && !(await cloudRefresh())) return false;
    await cloudPullQuiet();
    ok = await cloudPushQuiet();
  }catch(e){ ok = false; }
  finally{ _syncing = false; }
  return ok;
}

