  h += '<div class="kv"><span class="muted">Product lines</span><span>'+(b.products||1)+'</span></div>';
  h += '<div class="kv"><span class="muted">Locations</span><span>'+b.locations+'</span></div>';
  h += '</div>';
  h += '</div>';
  return h;
}

