          '<div class="tiny muted">Today\u2019s life \u00b7 '+esc(dealt.day)+'</div>'+
          '<div style="margin:6px 0 2px"><b>'+esc(P.name)+'</b> <span class="tiny muted">age '+P.age+' \u00b7 '+
