  let h = '<div class="between" style="margin-bottom:4px"><b>'+esc(a.name)+'</b>'+
    '<span class="chip b">you are playing this</span></div>'+
    '<div class="tiny muted" style="margin-bottom:10px">'+esc(a.desc)+'</div>'+
