      '<th>Tier</th><th>Odds</th><th>Coach</th><th>Replay</th><th>Pay</th><th></th>'+
    '</tr></thead><tbody>';
  keys.forEach(function(k){
    const dd = DIFFS[k], on = (k === act), locked = !tierUnlocked(k);
    h += '<tr'+(on?' class="on"':'')+'>'+
      '<td><b>'+esc(dd.name)+'</b></td>'+
      '<td>'+(dd.showOdds?'shown':'hidden')+'</td>'+
