  seasoncopylink: ()=>{
    const code = ((Q('seaCodeBox')||{}).value||'').trim() || seaDraftCode();
    const ok = copyText(seasonLink(code));
    toast(ok ? 'Invite link copied.' : 'Could not reach the clipboard — copy it from the box below.',
