        Math.round(maxBank*0.5), function(v){
          v = Math.min(v, maxBank);
          S.fin.debt.push({id:'d'+(++S.seq), name:'Bank facility', bal:v, rate:rate, minPay:Math.round(v*0.12), kind:'bank'});
