    const ratio = to.rentMult/from.rentMult;
    S.city = to.id;
    S.fin.budget.housing = Math.round(S.fin.budget.housing*ratio);
    S.fin.budget.food = Math.round(S.fin.budget.food*(0.6+0.4*ratio));
