    save('auto'); toast('Difficulty: '+DIFFS[k].name); render();
  },
  pickdiff: e=>{
    const k = e.dataset.d;
    if(!DIFFS[k]) return;
    if(!tierUnlocked(k)){ toast(tierLockNote(k), 3800); render(); return; }
    _cfg.difficulty = k; render();
  },
  profile:   e=>{ UI.modal = {type:'profile'}; render(); },
