  stepnext:  e=>{
    if((_cfg.step||1) === 1 && !String(inputValue('inName') || _cfg.name || '').trim()){
      toast('Give your character a name first.'); return;
    }
    if((_cfg.step||1) === 1) _cfg.name = inputValue('inName') || _cfg.name;
