  },
  stepback:  e=>{ _cfg.step = Math.max(1, (_cfg.step||1) - 1); UI.modal = {type:'start'}; render(); },
  /* every explanation the game has, shown or folded away: the world-first
     screen keeps the prose one tap off, never deleted */
