  bizinsure: ()=>{
    const b = S.biz; if(!b) return;
    const prem = Math.round(Math.max(180000, (b.revenue||0)*0.012)*S.cumInfl);
    if(b.insured===true){ message('Already covered','The policy is in force.'); return; }
