      '<div class="tiny muted" style="margin:6px 0">'+esc((BIZ.find(function(b){return b.id===rv.type;})||{name:rv.type}).name)+' · size '+Math.round(rv.size)+'/140 · aggression '+Math.round(rv.aggro)+'/100</div>'+
