  const rm    = net < 0 ? (cash / -net) : null;   /* months */
  const rq    = rm===null ? null : rm/3;          /* quarters */
  const runTxt  = rq===null ? 'Indefinite'
                : rq >= 12 ? '12+ qtrs'
                : rq >= 4  ? Math.round(rq)+' qtrs'
                : Math.max(1,Math.round(rm))+' month'+(Math.round(rm)===1?'':'s');
