    if (st.solar) { for (let i = 0; i < 5; i++) { const a = b.p(76 + i * 18, b.h + 6, 14), c2 = b.p(92 + i * 18, b.h + 6, 14), c3 = b.p(92 + i * 18, b.h + 14, 44), c4 = b.p(76 + i * 18, b.h + 14, 44); add(poly([a, c2, c3, c4], '#1c3767', ' stroke="#8fb3e8" stroke-width=".5"')); } }
