      add('<rect x="0" y="' + (groundY + 18) + '" width="390" height="14" fill="' + shade('#d6d0c4', dayK) + '"/><path d="M0 ' + (groundY + 18) + Array.from({ length: 40 }, () => ' q5 -9 10 0').join('') + ' V' + (groundY + 18) + 'Z" fill="' + shade('#3f6b3a', dayK) + '"/>');
