    : st.season === 'snow' ? ['#9aa3ad', '#c3c9cf', '#e4e7ea'] : /winter|autumn|cool/.test(st.season) ? ['#7d8794', '#a3abb5', '#c6cbd1'] : ['#5d9fd8', '#b8d6ea', '#efe3c6'];
