    '<filter id="' + id('grime') + '" x="0" y="0" width="1" height="1"><feTurbulence type="fractalNoise" baseFrequency=".055 .5" numOctaves="3" seed="' + ((st.seed || 11) % 9 + 3) + '"/>' +
