      s += '<line x1="' + f1(a[0]) + '" y1="' + f1((a[1] + c[1]) / 2) + '" x2="' + f1(c[0]) + '" y2="' + f1((a[1] + c[1]) / 2) + '" stroke="' + shade('#f2efe8', dayK) + '" stroke-width="1.6"/><line x1="' + f1((a[0] + c[0]) / 2) + '" y1="' + f1(a[1]) + '" x2="' + f1((a[0] + c[0]) / 2) + '" y2="' + f1(c[1]) + '" stroke="' + shade('#f2efe8', dayK) + '" stroke-width="1"/>';
    } else if (kind !== 'glass') {
      for (let i = 1; i < 5; i++) s += '<line x1="' + f1(a[0]) + '" y1="' + f1(a[1] + i * (c[1] - a[1]) / 5) + '" x2="' + f1(c[0]) + '" y2="' + f1(a[1] + i * (c[1] - a[1]) / 5) + '" stroke="#000" stroke-opacity=".25" stroke-width=".7"/>';   // louvre slats
      for (let i = 1; i < Math.floor((c[0] - a[0]) / 4); i++) s += '<line x1="' + f1(a[0] + i * 4) + '" y1="' + f1(a[1]) + '" x2="' + f1(a[0] + i * 4) + '" y2="' + f1(c[1]) + '" stroke="' + shade('#2b2b2b', dayK) + '" stroke-width=".9"/>';   // burglar-proof
    } else s += '<path d="M' + f1(a[0] + 3) + ' ' + f1(c[1] - 3) + 'L' + f1(a[0] + (c[0] - a[0]) * .45) + ' ' + f1(a[1] + 3) + '" stroke="#fff" stroke-opacity=".25" stroke-width="3"/>';
    if (kind !== 'glass' && !night) s += '<rect x="' + f1(a[0] + 1) + '" y="' + f1(c[1]) + '" width="' + f1(c[0] - a[0] - 2) + '" height="16" fill="' + url('streak') + '"/>';
    if (on) s += '<ellipse cx="' + f1((a[0] + c[0]) / 2) + '" cy="' + f1(c[1] + 4) + '" rx="' + f1((c[0] - a[0]) * 1.6) + '" ry="16" fill="' + url('spill') + '"/>';
    return s;
  };
  const door = (b, x, w, h, col) => { const a = b.p(x, h, 0), c = b.p(x + w, 0, 0); return '<rect x="' + f1(a[0]) + '" y="' + f1(a[1]) + '" width="' + f1(c[0] - a[0]) + '" height="' + f1(c[1] - a[1]) + '" fill="' + shade(col, dayK) + '" stroke="#1b130d" stroke-width="1"/><circle cx="' + f1(c[0] - 3) + '" cy="' + f1((a[1] + c[1]) / 2) + '" r=".9" fill="#d8c27a"/>'; };

  /* power lines: a concrete pole and the wires sagging across the street */
  const pole = (px) => {
    if (!skin.pole) {
      /* the wires are underground here: a street lamp */
      const lc = shade('#2b3036', Math.max(.7, dayK));
      return '<rect x="' + px + '" y="110" width="3" height="' + (groundY + 30 - 110) + '" fill="' + lc + '"/><path d="M' + (px + 1.5) + ' 112 q0 -8 -12 -8" stroke="' + lc + '" stroke-width="2.4" fill="none"/>' +
        '<path d="M' + (px - 18) + ' 104 h12 l-2 5 h-8z" fill="' + lc + '"/>' + (night || dusk ? '<ellipse cx="' + (px - 12) + '" cy="' + (groundY + 26) + '" rx="34" ry="9" fill="' + url('spill') + '"/><circle cx="' + (px - 12) + '" cy="110" r="3" fill="' + warm + '"/>' : '');
    }
    const top = 70, col = shade('#8d8a84', dayK);
    let s = '<rect x="' + px + '" y="' + top + '" width="4" height="' + (groundY + 30 - top) + '" fill="' + col + '"/><rect x="' + (px - 14) + '" y="' + (top + 6) + '" width="32" height="3" fill="' + col + '"/>';
    s += '<rect x="' + (px + 4) + '" y="' + (top + 40) + '" width="7" height="9" fill="' + shade('#556', dayK) + '"/>';   // transformer box
    [-12, -2, 10].forEach((dx, i) => { s += '<path d="M-10 ' + (top + 2 + i * 3) + ' Q' + (px / 2) + ' ' + (top + 24 + i * 4) + ' ' + (px + dx + 2) + ' ' + (top + 7) + ' Q' + ((px + W) / 2 + 20) + ' ' + (top + 30 + i * 5) + ' ' + (W + 10) + ' ' + (top + 14 + i * 4) + '" stroke="#1a1a1a" stroke-width=".8" fill="none" opacity=".75"/>'; });
    return s;
  };

  const car = (cx, cy, col, suv) => {
    const c = shade(col, dayK), r = suv ? 12 : 9;
    return '<g transform="translate(' + cx + ' ' + cy + ')"><ellipse cx="38" cy="23" rx="44" ry="5" fill="#000" opacity=".35" filter="' + url('blur1') + '"/>' +
      '<path d="M2 16 q0 -9 12 -10 l10 -' + r + ' q4 -2 10 -2 h' + (suv ? 22 : 16) + ' q6 0 10 4 l10 ' + (r - 2) + ' q12 2 14 8 v6 q0 3 -3 3 h-70 q-3 0 -3 -3z" fill="' + c + '"/>' +
      '<path d="M26 5 l7 -' + (r - 2) + ' h' + (suv ? 10 : 8) + ' v' + (r - 2) + 'z M' + (suv ? 47 : 43) + ' 5 v-' + (r - 2) + ' h' + (suv ? 10 : 7) + ' l8 ' + (r - 2) + 'z" fill="' + url('glassD') + '"/>' +
      '<path d="M4 15 h70" stroke="#fff" stroke-opacity=".28" stroke-width="1.2"/>' +
      '<circle cx="18" cy="22" r="6.5" fill="#141414"/><circle cx="60" cy="22" r="6.5" fill="#141414"/><circle cx="18" cy="22" r="3" fill="#aaa"/><circle cx="60" cy="22" r="3" fill="#aaa"/>' +
      (night ? '<path d="M76 14 l40 -6 v14z" fill="' + warm + '" opacity=".18"/>' : '') + '</g>';
  };
  const person = (px, py, o) => {
    const k = o.scale || 1, skin = shade(o.skin || '#6b4a32', Math.max(.55, dayK)), top = shade(o.shirt, dayK), legs = shade(o.legs || '#262b36', dayK);
    let s = '<g transform="translate(' + px + ' ' + py + ') scale(' + k + ')"><ellipse cx="3" cy="0" rx="9" ry="2.4" fill="#000" opacity=".3" filter="' + url('blur1') + '"/>';
    if (o.dress) s += '<path d="M-6.5 -24 h13 l3 24 h-19z" fill="' + top + '"/><path d="M-6.5 -24 h13 l3 24 h-19z" fill="' + shade(o.trim || '#f2c94c', dayK) + '" opacity=".35" transform="translate(0 -2) scale(1 .3)"/>';
    else s += '<path d="M-4.4 -15 h3.6 l-.2 15 h-3.4z M.8 -15 h3.6 l.2 15 h-3.4z" fill="' + legs + '"/>';
    s += '<path d="M-6.5 -31 q6.5 -3.5 13 0 l1.5 16 h-16z" fill="' + top + '"/><path d="M2 -31 q4.5 1 4.5 1 l1.5 16 h-6z" fill="#000" opacity=".16"/>';
    s += '<path d="M-6.5 -30 l-2 13" stroke="' + top + '" stroke-width="3" stroke-linecap="round"/><path d="M6.5 -30 l2 13" stroke="' + shade(o.shirt, dayK * .85) + '" stroke-width="3" stroke-linecap="round"/>';
    s += '<rect x="-1.5" y="-34" width="3" height="4" fill="' + skin + '"/><ellipse cx="0" cy="-38.5" rx="4.6" ry="5.2" fill="' + skin + '"/>';
    if (o.tie) s += '<path d="M0 -30 l-1.4 9 l1.4 2 l1.4 -2z" fill="#c9a227"/>';
    if (o.gele) s += '<path d="M-7 -41 q7 -10 14 0 q-3 -5 -7 -4 q-4 -1 -7 4z" fill="' + shade(o.gele, dayK) + '"/><path d="M5 -43 l5 -4 l-2 6z" fill="' + shade(o.gele, dayK) + '"/>';
    else if (o.cap) s += '<path d="M-5 -41 q5 -6 10 0z" fill="' + shade(o.cap, dayK) + '"/>';
    else s += '<path d="M-4.6 -40 q4.6 -6 9.2 0 q-4.6 -2.5 -9.2 0z" fill="' + (o.grey ? '#bdb8ae' : '#17110c') + '"/>';
    return s + '</g>';
  };
  const finish = (cls, label) => {
    /* a moment's people and things, laid over the place before the air */
    if (st.extra) add(typeof st.extra === 'function' ? st.extra(self) : st.extra);
    /* the air is something you look through, never something you tap */
    add('<g pointer-events="none">');
    if (st.season === 'rain') { let r = ''; for (let i = 0; i < 120 + Math.round(-TOP / 3); i++) { const x0 = rnd() * (W + 40) - 20, y0 = TOP + rnd() * VH; r += 'M' + f1(x0) + ' ' + f1(y0) + 'l-3 9'; } add('<path d="' + r + '" stroke="#dfe7ee" stroke-opacity=".45" stroke-width=".7"/>'); }
    if (st.season === 'snow') { let sn = ''; for (let i = 0; i < 140 + Math.round(-TOP / 3); i++) sn += '<circle cx="' + f1(rnd() * W) + '" cy="' + f1(TOP + rnd() * VH) + '" r="' + (rnd() * 1.2 + .5).toFixed(2) + '"/>'; add('<g fill="#fff" opacity=".8">' + sn + '</g>'); }
    if (/winter|autumn|cool/.test(st.season)) add('<rect y="' + TOP + '" width="' + W + '" height="' + VH + '" fill="#8a96a3" opacity=".12"/>');
    if (st.season === 'summer') add('<rect y="' + TOP + '" width="' + W + '" height="' + VH + '" fill="#ffd98a" opacity=".07"/>');
    if (st.season === 'harmattan') add('<rect y="' + TOP + '" width="' + W + '" height="' + VH + '" fill="#d9c09a" opacity=".16"/>');
    if (night) add('<rect y="' + TOP + '" width="' + W + '" height="' + VH + '" fill="#0a1030" opacity=".18"/>');
    add('<rect y="' + TOP + '" width="' + W + '" height="' + VH + '" filter="' + url('grain') + '" opacity=".9"/>');
    if (blackout && !st.gen && !st.solar && (night || dusk) && !st.noNepa && skin.outage) add('<text x="' + W / 2 + '" y="122" font-family="sans-serif" font-size="11" font-weight="700" text-anchor="middle" fill="' + warm + '" opacity=".85">' + esc(skin.outage) + '</text>');
    add('</g>');
    /* the places you can tap, over everything (VISUAL.md, M11) */
    if (st.hot) add(typeof st.hot === 'function' ? st.hot(self) : st.hot);
    return '<svg class="' + cls + '" viewBox="0 ' + TOP + ' ' + W + ' ' + VH + '" preserveAspectRatio="xMidYMax slice" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="' + esc(label) + '">' + out.join('') + '</svg>';
  };
  const self = {skin:skin, W:W, H:H, VH:VH, TOP:TOP, url:url, night:night, dusk:dusk, blackout:blackout, genOn:genOn, lights:lights,
    add:add, rnd:rnd, f1:f1, P:P, poly:poly, shade:shade, dayK:dayK, sideK:sideK, warm:warm, skyC:skyC, groundY:groundY,
    box:box, win:win, door:door, pole:pole, car:car, person:person, finish:finish};
  return self;
}

/* the people on their way, as a layer the scene's own kit draws: the nearer
   the quarter, the nearer the door */
function arrivalsLayer(items){
  return function(k){
    const gy = k.groundY, person = k.person, shade = k.shade, dayK = k.dayK, out = [];
    const soon = items.slice(0, 3);
    if (!soon.length) return '';
    out.push('<path d="M-10 ' + (gy + 112) + ' Q50 ' + (gy + 104) + ' 104 ' + (gy + 92) + '" stroke="#000" stroke-opacity=".14" stroke-width="10" fill="none" stroke-linecap="round"/>');
    soon.forEach(function(it, i){
      const q = Math.max(0, it.turn - S.turn);
      const x = 96 - Math.min(q, ROAD_QUARTERS - 1) * 12 - i * 6, y = gy + 104 - Math.min(q, ROAD_QUARTERS - 1) * 1.4 + i * 4;
      const s = 1.2 - Math.min(q, ROAD_QUARTERS - 1) * .05;
      const coat = it.kind === 'good' ? '#2fae6a' : it.kind === 'bad' ? '#3b3f46' : '#6f56b3';
      out.push(person(x, y, {shirt: coat, cap: it.kind === 'bad' ? '#2e3238' : null, skin: ['#5a3b27', '#4a3020', '#7d573b'][i % 3], scale: s}));
      /* what they carry, and above them the colour of the news */
      const hx = x + 8 * s, hy = y - 22 * s;
      out.push(it.kind === 'good'
        ? '<rect x="' + hx.toFixed(1) + '" y="' + hy.toFixed(1) + '" width="' + (8 * s).toFixed(1) + '" height="' + (4.5 * s).toFixed(1) + '" fill="' + shade('#2e8b57', dayK) + '" stroke="#fff" stroke-opacity=".4" stroke-width=".4"/>'
        : '<rect x="' + hx.toFixed(1) + '" y="' + (hy - 2).toFixed(1) + '" width="' + (6 * s).toFixed(1) + '" height="' + (8 * s).toFixed(1) + '" fill="' + shade('#f4f1e6', dayK) + '"/><circle cx="' + (hx + 4.5 * s).toFixed(1) + '" cy="' + (hy + 4.5 * s).toFixed(1) + '" r="' + (1.2 * s).toFixed(1) + '" fill="#b22222"/>');
      out.push('<circle cx="' + x.toFixed(1) + '" cy="' + (y - 58 * s).toFixed(1) + '" r="' + (4 * s).toFixed(1) + '" fill="' + (it.kind === 'good' ? '#2fd47a' : it.kind === 'bad' ? '#ff5f6d' : '#f5b301') + '" stroke="#0b1017" stroke-width="1"/>');
    });
    return out.join('');
  };
}

/* the road ahead, for the card: this quarter to eight from now, and each thing
   coming back at its quarter */
function roadAheadSVG(items){
  const W = 390, H = 74, x0 = 22, x1 = 368, step = (x1 - x0) / ROAD_QUARTERS, at = {};
  let s = '<svg class="gfx road" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + esc(items.length + ' thing' + (items.length === 1 ? '' : 's') + ' coming back to you over the next ' + ROAD_QUARTERS + ' quarters') + '">' +
    '<text x="' + x0 + '" y="12" font-family="sans-serif" font-size="10" font-weight="700" letter-spacing=".08em" fill="#8b9bb0">COMING BACK TO YOU</text>';
  s += '<path d="M' + x0 + ' 44 H' + x1 + '" stroke="rgba(255,255,255,.18)" stroke-width="6" stroke-linecap="round"/>';
  for (let q = 0; q <= ROAD_QUARTERS; q++) {
    const x = x0 + q * step;
    s += '<path d="M' + x.toFixed(1) + ' 39 v10" stroke="rgba(255,255,255,.3)" stroke-width="1.4"/>';
    if (q === 0 || q === 4 || q === ROAD_QUARTERS) s += '<text x="' + x.toFixed(1) + '" y="66" font-family="sans-serif" font-size="10" text-anchor="middle" fill="#8b9bb0">' + (q === 0 ? 'now' : '+' + q + 'q') + '</text>';
  }
  s += '<circle cx="' + x0 + '" cy="44" r="6" fill="#f5b301"/>';   // you are here
  items.forEach(function(it){
    const q = Math.max(0, Math.min(ROAD_QUARTERS, it.turn - S.turn)), n = at[q] = (at[q] || 0) + 1;
    if (n > 3) return;
    const x = x0 + q * step, y = 32 - (n - 1) * 11;
    s += '<g><title>' + esc(dateLabel(it.turn) + ': ' + it.title) + '</title>' +
      '<path d="M' + x.toFixed(1) + ' ' + (y + 6) + ' V40" stroke="' + arrivalTone(it.kind) + '" stroke-width="1.4" opacity=".7"/>' +
      '<circle cx="' + x.toFixed(1) + '" cy="' + y + '" r="6.5" fill="#0b1017" stroke="' + arrivalTone(it.kind) + '" stroke-width="2"/>' +
      (it.kind === 'good' ? '<path d="M' + (x - 3).toFixed(1) + ' ' + (y + 1) + 'l2 2 l4 -5" stroke="' + arrivalTone(it.kind) + '" stroke-width="1.6" fill="none"/>'
        : '<rect x="' + (x - 3).toFixed(1) + '" y="' + (y - 2.5) + '" width="6" height="5" fill="none" stroke="' + arrivalTone(it.kind) + '" stroke-width="1.2"/>') + '</g>';
  });
  return s + '</svg>';
}

/* the moment they arrive: at your gate, with what they carry, and you */
function arrivalHTML(items){
  if (!items || !items.length) return '';
  const home = homeLook();
  const layer = function(k){
    const gy = k.groundY, person = k.person, out = [];
    out.push(person(214, gy + 110, {shirt: S.p && S.p.job ? '#ece7dc' : '#3c79c4', legs: '#20242c', tie: !!(S.p && S.p.job), scale: 2.2}));
    items.slice(0, 3).forEach(function(it, i){
      const x = 120 - i * 46, y = gy + 112 - i * 2;
      out.push(person(x, y, {shirt: it.kind === 'good' ? '#2fae6a' : it.kind === 'bad' ? '#3b3f46' : '#6f56b3', cap: it.kind === 'bad' ? '#2e3238' : null, skin: ['#5a3b27', '#4a3020', '#7d573b'][i % 3], scale: 2.05}));
      const hx = x + 16, hy = y - 46;
      out.push(it.kind === 'good'
        ? '<g transform="translate(' + hx + ' ' + hy + ') rotate(-8)">' + [0, 1, 2].map(function(j){ return '<rect x="' + (j * 2) + '" y="' + (-j * 3) + '" width="20" height="10" rx="1" fill="' + ['#2e8b57', '#c05a7a', '#3b6ea8'][j] + '" stroke="#fff" stroke-opacity=".35"/>'; }).join('') + '</g>'
        : '<g transform="translate(' + hx + ' ' + (hy - 8) + ') rotate(6)"><rect width="16" height="20" fill="#f4f1e6" stroke="#999" stroke-width=".5"/><path d="M3 5h10M3 8h9M3 11h10" stroke="#888" stroke-width=".7"/><circle cx="12" cy="16" r="2.2" fill="#b22222"/></g>');
    });
    return out.join('');
  };
  return '<div class="moment">' + homeSceneSVG(Object.assign({}, home, {alone: true, extra: layer, label: 'At your gate: ' + items.map(function(i){ return i.title; }).join('; ')}), 250) + '</div>';
}

/* =========================================================================
   The boardroom (VISUAL.md, M7)
   ========================================================================= */
/* Governance is a room. Who owns the company is who sits at the table, and
   the size of their chair is the size of their stake; the register hangs on
   the wall as a picture of who owns what. When a resolution is open, the
   hands that would go up for it are up. When the company borrowed on
   covenants, the bank's man stands by the window with his folder, and when a
   covenant is breached the folder is red and he is not smiling. Read from the
   register, the board, the open resolutions and the covenants - and only
   read: the register is never created here (ensureGov() would write one), and
   a director's stance is the same pure reading the vote uses. */
function boardLook(){
  const air = homeLook(), b = S.biz;
  const base = {city: air.city, time: air.time, season: air.season, era: air.era, grid: air.grid, seed: 61};
  if(!b) return Object.assign(base, {none: true, label: 'No company, no boardroom'});
  const shares = b.shares || [], total = shares.reduce(function(s, h){ return s + (h.shares || 0); }, 0);
  const pctOf = function(h){ return total > 0 ? (h.shares || 0) / total * 100 : 0; };
  const mine = total > 0 ? shares.filter(function(h){ return h.you; }).reduce(function(s, h){ return s + pctOf(h); }, 0) : 100;
  const res = ((b.resolutions || []).filter(function(r){ return r.status === 'open'; }))[0] || null;
  /* who sits: the board if there is one, and you always */
  const board = (b.board || []).filter(function(d){ return !d.departed; });
  const seats = board.length ? board.map(function(d){
    const h = d.holderId ? shares.find(function(x){ return x.id === d.holderId; }) : null;
    return {name: d.name, yours: !!d.yours, chair: d.role === 'chair', label: d.label || '',
      pct: d.yours ? mine : h ? pctOf(h) : 0,
      vote: res ? dirStance(b, d, res).vote : ''};
  }) : [{name: S.name || 'You', yours: true, chair: true, label: 'founder', pct: mine, vote: res ? 'for' : ''}];
  if(!seats.some(function(x){ return x.yours; })) seats.push({name: S.name || 'You', yours: true, chair: false, label: 'shareholder', pct: mine, vote: ''});
  const holders = total > 0 ? shares.map(function(h){ return {you: !!h.you, pct: pctOf(h), name: h.name}; }) : [{you: true, pct: 100, name: S.name || 'You'}];
  const cov = b.covenants || [];
  const breached = cov.length ? covenantBreaches(b).length > 0 : false;
  return Object.assign(base, {none: false, name: b.name || 'Your company', seats: seats.slice(0, 7), holders: holders,
    res: res ? resMeta(res.kind).label : '', lender: cov.length > 0, breached: breached,
    label: (b.name || 'Your company') + ' boardroom: you hold ' + Math.round(mine) + '%' + (res ? ', a vote is open' : '') + (breached ? ', a covenant is breached' : '')});
}

